GRAPH_SHA = 'e931264aedee5458a3a825b5ec8dc4502354952137a375bf3e5c0c45ec299418'
SOURCE_FREEZE_SHA = '320c527de07e72c1399c0a0706e8b9f2be5ffe1a70682146dfd45035b4446a97'
CORE_HASHES = ['3c02940e2d4f3eb519f459dd658950df77662c7bd431500e52f2509658ed94fe', 'cffe4574c838fc54e1cf6b0ff9d190f06061798e2dc7eb906c12b7bbd7e2c39b', '1c50b1fcce4b79e3a88d74504486295a1dc4d0759c2bf944a3d0bf2e8979773d']

def need(ok, message):
    if not ok: raise ValueError(message)
def sha(b): return hashlib.sha256(b).hexdigest()
def diff(a,b,old,new):
    return b''.join(difflib.diff_bytes(difflib.unified_diff,a.splitlines(True),b.splitlines(True),fromfile=old.encode(),tofile=new.encode(),n=3))
def verify(root):
    root=root.resolve(); reads={}
    def read(name):
        p=PurePosixPath(name)
        need(not p.is_absolute() and '..' not in p.parts, 'Unsafe declared input')
        path=root.joinpath(*p.parts)
        need(path.is_file() and not path.is_symlink() and path.resolve().is_relative_to(root), 'Declared input missing or outside repository')
        if name not in reads: reads[name]=path.read_bytes()
        return reads[name]
    def pinned(name,digest,message):
        b=read(PACKET+'/'+name);need(sha(b)==digest,message);return json.loads(b)
    evidence=pinned('EVIDENCE_MAP.json',MAP_SHA,'Archive map changed')
    contents,origins={},{}
    for obj in evidence['objects']:
        need(obj['sha256'] not in contents,'Duplicate archive object')
        z=read(PACKET+'/'+obj['path'])
        need(sha(z)==obj['stored_sha256'] and len(z)==obj['stored_bytes'],'Compressed archive changed')
        b=gzip.decompress(z)
        need(sha(b)==obj['sha256'] and len(b)==obj['bytes'] and len(b.splitlines())==obj['lines'],'Archived source changed')
        contents[obj['sha256']]=b
        for origin in obj['origins']:
            need(origin['path'] not in origins,'Duplicate original alias');origins[origin['path']]=obj['sha256']
    def archived(name): return contents[origins[name]]
    contract=evidence['accepted_source_package'];prefix=contract['path']+'/'
    def source(name): return archived(prefix+name)
    need(contract['freeze_sha256']==SOURCE_FREEZE_SHA and sha(source('FINAL_FREEZE.json'))==SOURCE_FREEZE_SHA,'Accepted source freeze differs')
    seal=json.loads(source('FINAL_FREEZE.json'));members=contract['members'];extras=contract['additional_files']
    need(seal['members']==members and len(members)==contract['member_count']==90,'Assembly membership differs')
    need(len(extras)==1 and extras[0]['path']=='FINAL_FREEZE.json' and contract['complete_file_count']==91,'Assembly additional membership differs')
    need({p for p in origins if p.startswith(prefix)}=={prefix+r['path'] for r in members+extras},'Complete assembly aliases differ')
    for r in members+extras:
        b=source(r['path']);need(sha(b)==r['sha256'] and len(b)==r['bytes'],'Assembly member identity differs')
    selection=json.loads(source('SOURCE_ARCHIVE.json'))['members']
    need(len(selection)==evidence['original_source_selection_count']==49,'Original source selection differs')
    for r in selection:
        b=source(r['archive_path'])
        need(b==archived(r['source_path']) and sha(b)==r['sha256'] and len(b)==r['bytes'],'Original source alias differs')
    mapping=json.loads(source('SOURCE_MAP.json'));accepted=source(mapping['candidate']['path']);original_parts=[];cores=[];offset=0
    need(sha(accepted)==mapping['candidate']['sha256'] and len(accepted)==mapping['candidate']['bytes'],'Accepted candidate differs')
    for r in mapping['parts']:
        b=source(r['assembly_path']);end=offset+len(b)
        need(r['candidate_byte_start_inclusive']==offset and r['candidate_byte_end_exclusive']==end
             and accepted[offset:end]==b and sha(b)==r['sha256'] and len(b)==r['bytes'],'Original extraction differs')
        need(accepted[:offset].count(b'\n')+1==r['candidate_line_start_1based'] and accepted[:end].count(b'\n')==r['candidate_line_end_inclusive'],'Original extraction lines differ')
        original_parts.append(b);offset=end
        if r['assembly_path'].startswith('cores/'):
            need(b==source(r['original_archive_path']),'Complete proof-source alias differs');cores.append(b)
    need(b''.join(original_parts)==accepted and [sha(c) for c in cores]==CORE_HASHES,'Complete original bodies differ')
    edits=pinned('PUBLICATION_EDITS.json',EDITS_SHA,'Publication transformation changed')
    need(edits['source_freeze_sha256']==SOURCE_FREEZE_SHA and edits['additional_mathematical_body_edits']==[] and len(edits['notes'])==1,'Publication scope differs')
    need(edits['accepted_wrapper_edits']==0 and edits['accepted_candidate_preserved_as_exact_suffix'] is True,'Accepted source rewrite declared')
    note=edits['notes'][0];assembled=b'';published_cores=[];accepted_pieces=[]
    need(archived(note['accepted_candidate_path'])==accepted and sha(accepted)==note['accepted_candidate_sha256'],'Accepted publication candidate differs')
    for r in note['pieces']:
        if r['kind']=='publication_wrapper':
            b=r['text'].encode();need(r['wrapper_path']=='wrappers/PUBLICATION_FRONT.md','Unexpected publication wrapper')
        else:
            original=archived(r['source_path']);need(sha(original)==r['source_sha256'],'Full source identity differs')
            need(r['kind'] in ['accepted_wrapper','accepted_core_slice','accepted_framing'] and r['source_line_start']==1
                 and r['source_line_end']==len(original.splitlines()) and r['expected_slice_sha256']==sha(original)
                 and r['additional_mathematical_body_edits']==[],'Complete source slice differs');b=original
            if r['kind']=='accepted_core_slice':published_cores.append(b)
            accepted_pieces.append(b)
        need(sha(b)==r['sha256'] and len(b)==r['bytes'] and r['byte_offset']==len(assembled),'Publication piece bytes differ')
        need(r['first_line']==assembled.count(b'\n')+1 and r['last_line']==(assembled+b).count(b'\n'),'Publication piece lines differ');assembled+=b
    need(accepted_pieces==original_parts and published_cores==cores,'Accepted publication body order differs')
    actual=read(note['note'])
    need(actual==assembled and sha(actual)==note['published_sha256'] and len(actual)==note['published_bytes']
         and len(actual.splitlines())==note['published_lines'],'Published source does not reconstruct')
    def diff_bytes(r):
        z=read(PACKET+'/'+r['diff']);d=gzip.decompress(z)
        need(sha(z)==r['diff_stored_sha256'] and sha(d)==r['diff_sha256'] and len(d)==r['diff_bytes']
             and len(z)==r['stored_bytes'] and r['context_lines']==3,'Raw diff archive changed');return d
    need(diff_bytes(note)==diff(accepted,actual,note['fromfile'],note['tofile']),'Full publication diff differs')
    bindings=pinned('PARENT_BINDINGS.json',PARENTS_SHA,'Parent bindings changed')
    need(bindings['binding_complete'] is True and bindings['direct_edges_verified'] is True and bindings['markdown_citations_verified'] is True
         and bindings['publication_ancestry_is_not_mathematical_dependency'] is True
         and bindings['parents']==bindings['required_roles']==bindings['markdown_citations']==bindings['canonical_core_maps']==[],'External scientific dependency scope differs')
    need(json.loads(source('DEPENDENCIES.json'))['external_canonical_mathematical_dependencies']==[],'Accepted dependency scope differs')
    need(re.findall(r'\[[^\]]*\]\(([^)\s#]+\.md)(?:#[^)]*)?\)',actual.decode())==[],'Undeclared canonical Markdown citation')
    graph=pinned('CLAIM_REGISTRY_ADDITIONS.json',GRAPH_SHA,'Graph proposal changed')
    need(graph['binding_complete'] is True and len(graph['nodes'])==1 and graph['nodes'][0]['claim_id']==CLAIM
         and graph['nodes'][0]['path']==note['note']
         and graph['nodes'][0]['runner']=='scripts/interacting_copy_autonomous_controller_identity_2026_10_14.py'
         and graph['nodes'][0]['deps']==[] and graph['direct_edges']==[] and graph['new_roots']==[CLAIM]
         and graph['expected_delta']=={'nodes':1,'edges':0,'roots':1},'Independent graph root proposal differs')
    status=pinned('SOURCE_REVIEW_STATUS.json',STATUS_SHA,'Review scope changed')
    acceptance=read(PACKET+'/INTERACTING_COPY_ASSEMBLY_ROOT_ACCEPTANCE.json');review=read(PACKET+'/INTERACTING_COPY_ASSEMBLY_ROOT_REVIEW.md');scope=json.loads(acceptance)
    need(sha(acceptance)==status['source_assembly_root_acceptance_sha256'] and sha(review)==status['source_assembly_root_review_sha256'],'Assembly root review changed')
    need(scope==status['source_review_coverage_verbatim'] and scope['assembly_freeze_sha256']==SOURCE_FREEZE_SHA
         and scope['root_review_sha256']==sha(review) and scope['canonical_execution_authorized'] is False
         and scope['disposition']=='accepted_for_source_only_publication_preparation'
         and scope['external_canonical_mathematical_dependencies']==[] and scope['history_application_included'] is False,'Assembly acceptance scope differs')
    need(status['no_go_packet_pass'] is False and status['new_independent_mathematical_review'] is False
         and status['unchanged_complete_core_coverage_reused'] is True and status['mathematical_core_edits']==0
         and status['publication_runtime_executed_by_source_preparer'] is False and status['accepted_wrapper_edits']==0,'Review limitation differs')
    need(all(status[k] is True for k in ['supplied_interacting_copy_model','original_physical_source_and_arbitrary_reference','positive_full_clock_hamiltonian',
         'broad_and_narrow_error_classes_distinct','actual_energy_covariance_retained','fresh_fuel_width_qualification_retained',
         'engineered_six_qubit_finite_range_and_exponential_resources','one_declared_read_time','empty_external_mathematical_dependencies'])
         and all(status[k] is False for k in ['native_realization_proved','uniform_many_body_gap_proved','autonomous_stopping_proved',
         'history_application_included','kinetic_joint_limit_proved','retained_audit_status']),'Mandatory export scope changed')
    for name,p in EXTRA_PINS.items():
        b=read(name);need(sha(b)==p['sha256'] and len(b)==p['bytes'],'Additional publication integrity input changed')
    need(set(reads)==set(AUDIT_INPUT_PATHS) and len(AUDIT_INPUT_PATHS)==len(set(AUDIT_INPUT_PATHS)),'Declared read closure differs')
    return {'result':'source_identities_and_reconstruction_match','claim_id':CLAIM,'meaning':'Byte integrity only; no mathematical calculation, proof or audit executed.',
        'mathematical_operations_executed':False,'mathematical_predicates_executed':0,'scientific_mutations_executed':0,
        'no_go_packet_pass_supplied_by_tool':False,'independent_review_supplied_by_tool':False,
        'external_scientific_input_reads':[],'package_local_integrity_reads':sorted(reads)}
def main():
    print(json.dumps(verify(Path(__file__).resolve().parents[1]),sort_keys=True))
    print('per_element: checked and not executed — source integrity only; no collision-channel bound was evaluated.')
    print('per_site: checked and not executed — source integrity only; local strength and preparation remain supplied premises.')
    print('per_mode: checked and not executed — source integrity only; no clock spectrum or positivity predicate was evaluated.')
    print('per_block: checked and not executed — source integrity only; no structured-error or covariance calculation ran.')
    print('lattice_wide: checked and not executed — source integrity only; no interacting-controller inequality or native/stopping theorem was verified.')
if __name__=='__main__':
    try: main()
    except Exception as error:
        print(json.dumps({'result':'identity_verification_incomplete','error':str(error),'mathematical_operations_executed':False,
            'mathematical_predicates_executed':0,'scientific_mutations_executed':0}),file=sys.stderr)
        raise SystemExit(1)
